+// A puff of dust (a landing's, a jet's on the ground): a camera-facing quad, a
+// soft ragged cloud in the ground's colour, lit by the sun a little, fading out.
+shader_type spatial;
+render_mode cull_disabled, depth_draw_never, blend_mix, shadows_disabled;
+
+uniform sampler3D noise_tex : filter_linear, repeat_enable;
+uniform vec4 tint : source_color = vec4(0.55, 0.5, 0.42, 1.0);
+instance uniform float fade = 1.0;
+instance uniform float seed = 0.0;
+
+void vertex() {
+	MODELVIEW_MATRIX = VIEW_MATRIX * mat4(INV_VIEW_MATRIX[0], INV_VIEW_MATRIX[1], INV_VIEW_MATRIX[2], MODEL_MATRIX[3]);
+	MODELVIEW_MATRIX = MODELVIEW_MATRIX * mat4(vec4(length(MODEL_MATRIX[0].xyz), 0.0, 0.0, 0.0), vec4(0.0, length(MODEL_MATRIX[1].xyz), 0.0, 0.0), vec4(0.0, 0.0, length(MODEL_MATRIX[2].xyz), 0.0), vec4(0.0, 0.0, 0.0, 1.0));
+}
+
+void fragment() {
+	vec2 c = UV * 2.0 - 1.0;
+	float n = texture(noise_tex, vec3(UV * 0.35, seed)).r * 0.6 + texture(noise_tex, vec3(UV * 0.8, seed + 0.5)).r * 0.4;
+	float a = smoothstep(1.0, 0.1, length(c) + (n - 0.5) * 1.3) * (0.55 + n * 0.6);
+	ALBEDO = tint.rgb * (0.85 + n * 0.3);
+	BACKLIGHT = ALBEDO * 0.8;   // (light through the cloud: lit from behind too)
+	ROUGHNESS = 1.0;
+	SPECULAR = 0.0;
+	NORMAL = normalize(NORMAL + vec3(c * 0.6, 0.0));
+	ALPHA = clamp(a, 0.0, 1.0) * fade * 0.5;
+}

